        const ids = transactionIDsKey ? transactionIDsKey.split('|') : [];
        return ids.map((id) => {
            const tx = collection?.[`${ONYXKEYS.COLLECTION.TRANSACTION}${id}`];
            return tx ? {transactionID: tx.transactionID, reportID: tx.reportID} : undefined;
