Both `getReportFieldValues()` and `getReportFieldsByName()` call `getAvailableReportFields()` independently, which performs filtering and processing of the field list. When used in components like `MoneyReportView.tsx`, this means `getAvailableReportFields()` is called 3 times with the same inputs:
1. Once in `sortedPolicyReportFields`
2. Once in `fieldValues`  
3. Once in `fieldsByName`

This triples the work of filtering and processing fields.

**Fix**: Either:
1. Accept pre-filtered fields as a parameter to avoid redundant calls:

```typescript
function getReportFieldValues(fields: PolicyReportField[]): Record<string, string> {
    const values: Record<string, string> = {};
    for (const field of fields) {
        if (field.name) {
            values[field.name.toLowerCase()] = field.value ?? field.defaultValue ?? '';
        }
    }
    return values;
}

function getReportFieldsByName(fields: PolicyReportField[]): Record<string, PolicyReportField> {
    const fieldsByName: Record<string, PolicyReportField> = {};
    for (const field of fields) {
        if (field.name) {
            fieldsByName[field.name.toLowerCase()] = field;
        }
    }
    return fieldsByName;
}
```

2. Or combine into a single function that returns both maps:

```typescript
function getReportFieldMaps(report: OnyxEntry<Report>, fieldList: Record<string, PolicyReportField>): {
    fieldValues: Record<string, string>;
    fieldsByName: Record<string, PolicyReportField>;
} {
    const fields = getAvailableReportFields(report, Object.values(fieldList ?? {}));
    const fieldValues: Record<string, string> = {};
    const fieldsByName: Record<string, PolicyReportField> = {};

    for (const field of fields) {
        if (field.name) {
            const lowerName = field.name.toLowerCase();
            fieldValues[lowerName] = field.value ?? field.defaultValue ?? '';
            fieldsByName[lowerName] = field;
        }
    }

    return {fieldValues, fieldsByName};
}
```

