**File**: src/hooks/useTransactionsByID.ts:7

This refactoring causes the component to subscribe to ALL transactions in the collection, which can lead to unnecessary re-renders whenever ANY transaction changes, not just the specific transactions needed by `transactionIDs`.

**Problem**: The old selector pattern only caused re-renders when the specific transactions in `transactionIDs` changed. The new approach loads the entire `ONYXKEYS.COLLECTION.TRANSACTION` object and filters it in `useMemo`, meaning the component re-renders whenever ANY transaction in the collection changes, even if it's not in the `transactionIDs` array.

**Suggested fix**: Keep the selector pattern for optimal performance:

```typescript
import {useCallback} from 'react';
import type {OnyxCollection} from 'react-native-onyx';
import ONYXKEYS from '@src/ONYXKEYS';
import type {Transaction} from '@src/types/onyx';
import useOnyx from './useOnyx';

function useTransactionsByID(transactionIDs: string[] | undefined) {
    const transactionsSelector = useCallback(
        (transactions: OnyxCollection<Transaction>) => 
            transactionIDs?.map((id) => transactions?.[&#96;&#36;{ONYXKEYS.COLLECTION.TRANSACTION}&#36;{id}&#96;]).filter(Boolean) as Transaction[] ?? [],
        [transactionIDs],
    );

    const [transactions] = useOnyx(
        ONYXKEYS.COLLECTION.TRANSACTION,
        {
            selector: transactionsSelector,
            canBeMissing: true,
        },
        [transactionsSelector],
    );

    return [transactions];
}

export default useTransactionsByID;
```

This ensures that the component only re-renders when the specific transactions in `transactionIDs` change, not when any transaction in the entire collection changes.

